__NBS_MODULES["TraficLight/src/phases"] = function(require)
    local Config = require("TraficLight/src/config")
    
    local Phases = {}
    local Phase = {
    	Green = "green",
    	Red = "red",
    }
    
    local phase = Phase.Green
    local phaseStart: number? = nil
    local phaseEnd = 0
    local warningSent = false
    local beforeRedTicks = Config.warning.beforeRedTicks
    
    function Phases.update(now: number): boolean
    	if phaseStart ~= nil and now < phaseEnd then
    		return false
    	end
    
    	if phaseStart ~= nil then
    		phase = phase == Phase.Green and Phase.Red or Phase.Green
    	end
    
    	local duration = phase == Phase.Green and Config.green or Config.red
    	phaseStart = now
    	-- Верхняя граница getRandomInt исключается.
    	phaseEnd = now + server:getRandomInt(duration.minTicks, duration.maxTicks + 1)
    	warningSent = false
    	return true
    end
    
    function Phases.isGreen(): boolean
    	return phase == Phase.Green
    end
    
    function Phases.shouldWarn(now: number, phaseChanged: boolean): boolean
    	local warningDue = Phases.isGreen()
    		and not warningSent
    		and now >= phaseEnd - beforeRedTicks
    
    	if warningDue then
    		warningSent = true
    		beforeRedTicks = math.max(
    			Config.warning.minBeforeRedTicks,
    			beforeRedTicks - Config.warning.decreasePerCycleTicks
    		)
    	end
    	return (phaseChanged and Phases.isGreen()) or warningDue
    end
    
    function Phases.getSprayIndex(now: number): number?
    	if phase == Phase.Red then
    		return Config.spray.redIndex
    	end
    	if phaseStart ~= nil and now - phaseStart < Config.spray.greenTicks then
    		return Config.spray.greenIndex
    	end
    	return nil
    end
    
    return Phases
end

