__NBS_MODULES["TraficLight/src/signals"] = function(require)
    local Config = require("TraficLight/src/config")
    local Types = require("TraficLight/src/types")
    
    type PlayerState = Types.PlayerState
    
    local Signals = {}
    local warningData = Config.warning.enabled and lookup(Config.warning.dataType, Config.warning.name)
    local sprayData = Config.spray.enabled and lookup(Config.spray.dataType, Config.spray.name)
    
    function Signals.warning(character: LogicCharacter): ()
    	if not warningData then
    		return
    	end
    
    	local options = Config.warning
    	local effect = character:spawnCirclingAreaEffect(
    		options.damageBonus,
    		warningData :: AreaEffectData,
    		AttackOrigin.UNKNOWN,
    		options.applyOwnerBuffs,
    		options.followOwner
    	)
    	effect:setPosition(character.x, character.y, options.z)
    end
    
    function Signals.clear(state: PlayerState): ()
    	if state.spray ~= nil and state.spray:isAlive() then
    		state.spray:destroy()
    	end
    	state.spray = nil
    	state.sprayIndex = nil
    end
    
    function Signals.update(state: PlayerState, index: number?): ()
    	if not sprayData or index == nil then
    		Signals.clear(state)
    		return
    	end
    	local character = state.character
    	if state.sprayIndex ~= index or state.spray == nil or not state.spray:isAlive() then
    		Signals.clear(state)
    		local spray = createObject(sprayData) :: LogicItem
    		spray:setIndex(character.index, character.team)
    		spray.sprayDataIndex = index
    		spray:setPosition(character.x, character.y, Config.spray.z)
    		server.objectManager:addObject(spray)
    		state.spray = spray
    		state.sprayIndex = index
    	else
    		state.spray:setPosition(character.x, character.y, Config.spray.z)
    	end
    end
    
    return Signals
end

