__NBS_MODULES["TraficLight/src/movement"] = function(require)
    local Config = require("TraficLight/src/config")
    local Types = require("TraficLight/src/types")
    
    type PlayerState = Types.PlayerState
    
    local Movement = {}
    local toleranceSquared = Config.movement.tolerance * Config.movement.tolerance
    
    function Movement.savePose(state: PlayerState): ()
    	local character = state.character
    	state.x = character.x
    	state.y = character.y
    	state.z = character.z
    	state.angleHead = character.angleHead
    	state.angleLegs = character.angleLegs
    end
    
    local function angleDifference(current: number, previous: number): number
    	return math.abs((current - previous + 180) % 360 - 180)
    end
    
    function Movement.hasMoved(state: PlayerState): boolean
    	local character = state.character
    	local options = Config.movement
    	local dx = character.x - state.x
    	local dy = character.y - state.y
    	local dz = options.checkHeight and character.z - state.z or 0
    
    	if dx * dx + dy * dy + dz * dz > toleranceSquared then
    		return true
    	end
    	if not options.checkRotation then
    		return false
    	end
    
    	return angleDifference(character.angleHead, state.angleHead) > options.angleTolerance
    		or angleDifference(character.angleLegs, state.angleLegs) > options.angleTolerance
    end
    
    return Movement
end

