__NBS_MODULES["TraficLight/src/players"] = function(require)
    local Config = require("TraficLight/src/config")
    local Signals = require("TraficLight/src/signals")
    local Movement = require("TraficLight/src/movement")
    local Damage = require("TraficLight/src/damage")
    local Phases = require("TraficLight/src/phases")
    local Types = require("TraficLight/src/types")
    
    type PlayerState = Types.PlayerState
    
    local Players = {}
    local players: { [number]: PlayerState } = {}
    
    local function getCharacter(index: number, state: PlayerState?): LogicCharacter?
    	local client = server:getClientInfo(index)
    	local character = state and state.character
    
    	if character == nil or character.id ~= client.objectId then
    		if state ~= nil then
    			Signals.clear(state)
    		end
    		local object = client.objectId >= 0 and server.objectManager:getObject(client.objectId) or nil
    		character = nil
    		if object ~= nil and object:getType() == 0 then
    			character = object :: LogicCharacter
    		end
    	end
    
    	if character == nil or character.type ~= CharacterType.HERO or not character:isAlive() then
    		return nil
    	end
    	if character.isBot and not Config.movement.includeBots then
    		return nil
    	end
    	return character
    end
    
    local function updatePlayer(index: number, phaseChanged: boolean, showWarning: boolean, sprayIndex: number?): ()
    	local state = players[index]
    	local character = getCharacter(index, state)
    
    	if character == nil then
    		if state ~= nil then
    			Signals.clear(state)
    		end
    		players[index] = nil
    		return
    	end
    
    	if state == nil then
    		state = {
    			character = character,
    			x = character.x,
    			y = character.y,
    			z = character.z,
    			angleHead = character.angleHead,
    			angleLegs = character.angleLegs,
    			condemned = false,
    			spray = nil,
    			sprayIndex = nil,
    		}
    		players[index] = state
    	end
    	state.character = character
    
    	if Phases.isGreen() or phaseChanged then
    		Movement.savePose(state)
    	elseif Movement.hasMoved(state) then
    		state.condemned = true
    	end
    
    	if state.condemned then
    		-- Повторяем, если временная защита отклонила предыдущий урон.
    		Damage.kill(character)
    		Signals.clear(state)
    		return
    	end
    
    	if showWarning then
    		Signals.warning(character)
    	end
    	Signals.update(state, sprayIndex)
    end
    
    function Players.update(phaseChanged: boolean, showWarning: boolean, sprayIndex: number?): ()
    	for index = 0, server.playersCount - 1 do
    		updatePlayer(index, phaseChanged, showWarning, sprayIndex)
    	end
    end
    
    function Players.clear(): ()
    	for _, state in pairs(players) do
    		Signals.clear(state)
    	end
    end
    
    return Players
end

