-- Module: TraficLight/src/main
-- Source: TraficLight/src/main.luau
-- ============================================================
__NBS_MODULES["TraficLight/src/main"] = function(require)
    local Config = require("TraficLight/src/config")
    local Phases = require("TraficLight/src/phases")
    local Players = require("TraficLight/src/players")
    local started = false
    
    server.hasIntroSkip = Config.server.skipIntro
    server.hasPoisonDisabled = Config.server.disablePoison
    
    function tick(): ()
    	if server.isBattleEnded then
    		Players.clear()
    		return
    	end
    	if not server:isIntroFinished() then
    		return
    	end
    
    	local now = server.tick
    	if not started then
    		started = true
    		if Config.chat.enabled then
    			log(Config.chat.rulesMessage)
    		end
    	end
    
    	local phaseChanged = Phases.update(now)
    	if phaseChanged and Config.chat.enabled then
    		log(Phases.isGreen() and Config.chat.greenMessage or Config.chat.redMessage)
    	end
    	local showWarning = Phases.shouldWarn(now, phaseChanged)
    	local sprayIndex = Phases.getSprayIndex(now)
    
    	Players.update(phaseChanged, showWarning, sprayIndex)
    end
end

__NBS_REQUIRE("TraficLight/src/main")
